#!/usr/bin/env node
// Builds the `knowledge-graph` and `knowledge-setup` skills of the standalone
// `nimbalyst-wiki` Claude Code plugin from the knowledge extension's skills, so
// the desktop plugin and the remote plugin share one source of writing
// guidance. The desktop skills call the loopback `tracker_*` tools; the remote
// plugin talks to the wiki server's `wiki_*` tools, which also take `repo`.
//
//   node scripts/build-wiki-plugin.mjs          write plugins/nimbalyst-wiki/skills/...
//   node scripts/build-wiki-plugin.mjs --check  exit 1 if the generated files are stale

import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const DEFAULT_SOURCE = path.join(REPO_ROOT, 'packages/extensions/knowledge/claude-plugin/skills');
export const DEFAULT_TARGET = path.join(REPO_ROOT, 'plugins/nimbalyst-wiki/skills');
export const GENERATED_SKILLS = ['knowledge-graph', 'knowledge-setup'];

// Tool contract rev 3 (changesets required since rev 9). Keep in sync with the server's `wiki_*` tool names.
export const TOOL_RENAMES = {
  tracker_list_types: 'wiki_list_types',
  tracker_define_type: 'wiki_define_type',
  tracker_list: 'wiki_list',
  tracker_get: 'wiki_get',
  tracker_create: 'wiki_create_item',
  tracker_update: 'wiki_update_item',
};

const SOURCE_LABEL = 'packages/extensions/knowledge/claude-plugin/skills';
const GENERATED_NOTE = `GENERATED by scripts/build-wiki-plugin.mjs from ${SOURCE_LABEL}. Do not edit; edit the source and re-run the script.`;

// The desktop MCP prefix is consumed too: the plugin's tools come from a
// different server, so a prefixed name would never resolve.
const RENAME_PATTERN = new RegExp(
  `(?:mcp__nimbalyst-trackers__|(?<![A-Za-z0-9_]))(${Object.keys(TOOL_RENAMES).join('|')})(?![A-Za-z0-9_])`,
  'g',
);
const LEFTOVER_PATTERN = /mcp__nimbalyst-trackers__\w*|(?<![A-Za-z0-9_])tracker_[a-z]+(?:_[a-z]+)*/g;

const REMOTE_PREAMBLE = [
  '> **Remote wiki tools.** This copy of the skill runs against the Nimbalyst wiki server, not the desktop app.',
  'Every `wiki_*` call takes `repo` (the output of `git remote get-url origin`) and, when `.nimbalyst/wiki.json`',
  'pins one, `project: { orgId, projectId }`. Every write (`wiki_create_item`, `wiki_update_item`,',
  '`wiki_define_type`) requires a `changesetId` from `wiki_begin_changeset`. The `wiki-keeper` skill covers',
  'resolving the project and changesets.',
].join(' ');

// The source skills mark passages that only hold for one side. Desktop-only
// passages (personal/team sharing, drafts, the local predicates file) are
// dropped here; remote-only passages sit in an HTML comment the desktop skill
// never renders and are unwrapped here.
const DESKTOP_ONLY_BLOCK = /<!-- desktop-only -->\n[\s\S]*?<!-- \/desktop-only -->\n/g;
const REMOTE_ONLY_BLOCK = /<!-- remote-only\n([\s\S]*?)\n-->\n/g;
const STRAY_MARKER = /<!-- \/?(?:desktop|remote)-only\b/;

export function applyRemoteBranch(text, fileLabel = '<text>') {
  if (!text.includes('-only')) return text;
  const out = text
    .replace(DESKTOP_ONLY_BLOCK, '')
    .replace(REMOTE_ONLY_BLOCK, '$1\n')
    // A dropped block between two paragraphs leaves both blank lines behind.
    .replace(/\n{3,}/g, '\n\n');
  if (STRAY_MARKER.test(out)) throw new Error(`${fileLabel}: unbalanced desktop-only/remote-only marker`);
  return out;
}

export function rewriteToolNames(text, fileLabel = '<text>') {
  const rewritten = text.replace(RENAME_PATTERN, (_match, name) => TOOL_RENAMES[name]);
  const leftovers = [...new Set(rewritten.match(LEFTOVER_PATTERN) ?? [])];
  if (leftovers.length > 0) {
    throw new Error(`${fileLabel}: no wiki_* mapping for ${leftovers.join(', ')}; extend TOOL_RENAMES`);
  }
  return rewritten;
}

function injectSkillHeader(text, fileLabel) {
  const match = /^---\n[\s\S]*?\n---\n/.exec(text);
  if (!match) throw new Error(`${fileLabel}: SKILL.md has no frontmatter`);
  const frontmatter = match[0];
  const body = text.slice(frontmatter.length).replace(/^\n+/, '');
  const referencesNote = 'Its references/ files are generated from the same source.';
  return `${frontmatter}\n<!-- ${GENERATED_NOTE} ${referencesNote} -->\n\n${REMOTE_PREAMBLE}\n\n${body}`;
}

function transformFile(relPath, text) {
  const rewritten = rewriteToolNames(applyRemoteBranch(text, relPath), relPath);
  if (path.basename(relPath) === 'SKILL.md') return injectSkillHeader(rewritten, relPath);
  if (/\.ya?ml$/.test(relPath)) return `# ${GENERATED_NOTE}\n${rewritten}`;
  // Other references (wiki-guide.md) are copied verbatim into wiki pages by the
  // setup skill, so a header here would end up in the team's guide page. The
  // owning SKILL.md carries the generated marker for them.
  return rewritten;
}

function listFiles(dir, base = dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? listFiles(full, base) : [path.relative(base, full).split(path.sep).join('/')];
  });
}

/** Returns Map<relative path under skills/, generated content>. */
export function buildGeneratedFiles(sourceDir = DEFAULT_SOURCE) {
  const files = new Map();
  for (const skill of GENERATED_SKILLS) {
    const skillDir = path.join(sourceDir, skill);
    for (const rel of listFiles(skillDir).sort()) {
      const relPath = `${skill}/${rel}`;
      files.set(relPath, transformFile(relPath, readFileSync(path.join(skillDir, rel), 'utf8')));
    }
    if (!files.has(`${skill}/SKILL.md`)) throw new Error(`${skill}: missing SKILL.md in ${skillDir}`);
  }
  return files;
}

/** Lists generated paths that are missing, different, or no longer produced. */
export function checkGenerated({ sourceDir = DEFAULT_SOURCE, targetDir = DEFAULT_TARGET } = {}) {
  const expected = buildGeneratedFiles(sourceDir);
  const stale = [];
  for (const [relPath, content] of expected) {
    const onDisk = path.join(targetDir, relPath);
    if (!existsSync(onDisk)) stale.push(`missing: ${relPath}`);
    else if (readFileSync(onDisk, 'utf8') !== content) stale.push(`changed: ${relPath}`);
  }
  for (const skill of GENERATED_SKILLS) {
    for (const rel of listFiles(path.join(targetDir, skill))) {
      if (!expected.has(`${skill}/${rel}`)) stale.push(`extra: ${skill}/${rel}`);
    }
  }
  return stale;
}

export function writeGenerated({ sourceDir = DEFAULT_SOURCE, targetDir = DEFAULT_TARGET } = {}) {
  const files = buildGeneratedFiles(sourceDir);
  // Only the generated skill directories are replaced; hand-written skills
  // (wiki-keeper) live beside them and are never touched.
  for (const skill of GENERATED_SKILLS) rmSync(path.join(targetDir, skill), { recursive: true, force: true });
  for (const [relPath, content] of files) {
    const out = path.join(targetDir, relPath);
    mkdirSync(path.dirname(out), { recursive: true });
    writeFileSync(out, content);
  }
  return [...files.keys()];
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--check')) {
    const stale = checkGenerated();
    if (stale.length > 0) {
      console.error(`nimbalyst-wiki generated skills are stale:\n  ${stale.join('\n  ')}\nRun: node scripts/build-wiki-plugin.mjs`);
      process.exit(1);
    }
    console.log('nimbalyst-wiki generated skills are up to date.');
  } else {
    const written = writeGenerated();
    console.log(`Wrote ${written.length} files to ${path.relative(REPO_ROOT, DEFAULT_TARGET)}`);
  }
}
